"use client";

import { useState, useMemo } from "react";
import { useParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  Network,
  Building,
  Globe,
  Search,
  X,
  Shield,
  Zap,
  Wifi,
  WifiOff,
} from "lucide-react";
import Link from "next/link";
import Flag from "@/components/ui/Flag";
import { useASNData } from "@/hooks/useData";
import Skeleton from "@/components/ui/Skeleton";
import Pagination from "@/components/ui/Pagination";
import { detectIPVersion } from "@/lib/ipUtils";

export default function ASNCountryPage() {
  const params = useParams();
  const countryCode = params.countryCode as string;
  const { data, loading } = useASNData(countryCode);
  const [currentPage, setCurrentPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState("");
  const itemsPerPage = 20;

  const groupedData = useMemo(() => {
    return data.reduce(
      (acc, entry) => {
        if (!acc[entry.asn]) {
          acc[entry.asn] = [];
        }
        acc[entry.asn].push(entry);
        return acc;
      },
      {} as Record<string, typeof data>,
    );
  }, [data]);

  const asnInfo = useMemo(() => {
    const info: Record<
      string,
      {
        asn: string;
        name: string;
        org: string;
        count: number;
        ipv4: number;
        ipv6: number;
      }
    > = {};
    for (const [asn, entries] of Object.entries(groupedData)) {
      const firstEntry = entries[0];
      const ipv4 = entries.filter(
        (e) => detectIPVersion(e.network) === "IPv4",
      ).length;
      const ipv6 = entries.filter(
        (e) => detectIPVersion(e.network) === "IPv6",
      ).length;
      info[asn] = {
        asn,
        name: firstEntry?.name || "",
        org: firstEntry?.org || "",
        count: entries.length,
        ipv4,
        ipv6,
      };
    }
    return info;
  }, [groupedData]);

  const filteredAsnKeys = useMemo(() => {
    if (!searchQuery.trim()) {
      return Object.keys(groupedData);
    }

    const query = searchQuery.toLowerCase().trim();
    return Object.keys(groupedData).filter((asn) => {
      const info = asnInfo[asn];
      return (
        asn.includes(query) ||
        info.name.toLowerCase().includes(query) ||
        info.org.toLowerCase().includes(query)
      );
    });
  }, [groupedData, asnInfo, searchQuery]);

  const totalPages = Math.ceil(filteredAsnKeys.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentAsns = filteredAsnKeys.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleSearch = (value: string) => {
    setSearchQuery(value);
    setCurrentPage(1);
  };

  const clearSearch = () => {
    setSearchQuery("");
    setCurrentPage(1);
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-32 w-full" variant="card" />
        <Skeleton className="h-12 w-full" />
        <div className="grid grid-cols-1 gap-4">
          {[...Array(5)].map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-[rgba(34,229,122,.08)] border border-[rgba(34,229,122,.1)] mb-4">
          <Network size={28} className="text-[#4f6459]" />
        </div>
        <p className="text-[#93a79d] font-mono">
          No ASN data found for {countryCode.toUpperCase()}
        </p>
        <Link
          href="/asn"
          className="inline-flex items-center gap-2 text-[#22e57a] hover:text-[#5cffa5] mt-4 transition-colors font-mono text-sm"
        >
          <ArrowLeft size={14} />
          Back to ASN overview
        </Link>
      </div>
    );
  }

  const totalNetworks = data.length;
  const totalAsns = Object.keys(groupedData).length;
  const filteredCount = filteredAsnKeys.length;

  return (
    <div className="space-y-6">
      {/* Back Button */}
      <Link
        href="/asn"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to ASN overview
      </Link>

      {/* Header Card */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-[#070b09]/80 backdrop-blur-sm border border-[rgba(34,229,122,.12)] rounded-xl p-6"
      >
        <div className="flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="flex items-center gap-6">
            <div className="flex-shrink-0">
              <Flag countryCode={countryCode} size={56} variant="rounded" />
            </div>
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold font-mono text-[#f2fff8]">
                ASN Database — {countryCode.toUpperCase()}
              </h1>
              <div className="flex flex-wrap items-center gap-4 text-sm mt-1.5">
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <Network size={15} />
                  {totalAsns.toLocaleString()} ASNs
                </span>
                <span className="flex items-center gap-1.5 text-[#6f8a7d]">
                  <Globe size={15} />
                  {totalNetworks.toLocaleString()} networks
                </span>
                {searchQuery && (
                  <span className="text-[#22e57a] font-mono text-xs">
                    {filteredCount.toLocaleString()} filtered
                  </span>
                )}
              </div>
            </div>
          </div>
          {totalPages > 1 && !searchQuery && (
            <div className="lg:ml-auto text-xs font-mono text-[#4f6459]">
              Page {currentPage} of {totalPages}
            </div>
          )}
        </div>
      </motion.div>

      {/* Search Bar */}
      <div className="relative">
        <div className="relative">
          <Search
            className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6f8a7d]"
            size={16}
          />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder={`Search ASNs in ${countryCode.toUpperCase()}...`}
            className="w-full bg-[#070b09]/60 border border-[rgba(34,229,122,.1)] rounded-xl pl-10 pr-10 py-3 text-sm text-[#c6d2ca] placeholder-[#4f6459] focus:outline-none focus:border-[rgba(34,229,122,.3)] focus:ring-1 focus:ring-[rgba(34,229,122,.15)] transition-all duration-200 font-mono"
          />
          {searchQuery && (
            <button
              onClick={clearSearch}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-[#4f6459] hover:text-[#6f8a7d] transition-colors p-1 rounded-md hover:bg-[rgba(34,229,122,.06)]"
            >
              <X size={16} />
            </button>
          )}
        </div>
        {searchQuery && (
          <div className="mt-2 text-xs font-mono text-[#6f8a7d]">
            Found {filteredCount.toLocaleString()} ASN
            {filteredCount !== 1 ? "s" : ""} matching "{searchQuery}"
          </div>
        )}
      </div>

      {/* ASN List */}
      <div className="grid grid-cols-1 gap-3">
        {currentAsns.length > 0 ? (
          currentAsns.map((asn, index) => {
            const entries = groupedData[asn];
            const firstEntry = entries[0];
            const info = asnInfo[asn];
            const hasBoth = info.ipv4 > 0 && info.ipv6 > 0;

            return (
              <motion.div
                key={asn}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.04 }}
              >
                <Link
                  href={`/asn/${countryCode}/${asn}`}
                  className="block bg-[#070b09]/60 border border-[rgba(34,229,122,.06)] hover:border-[rgba(34,229,122,.2)] rounded-xl p-4 transition-all duration-300 group"
                >
                  <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                    <div className="flex-shrink-0 w-11 h-11 bg-[rgba(34,229,122,.06)] rounded-xl flex items-center justify-center border border-[rgba(34,229,122,.08)] group-hover:border-[rgba(34,229,122,.2)] transition-colors">
                      <Network size={22} className="text-[#22e57a]" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-mono font-bold text-lg text-[#22e57a]">
                          AS{asn}
                        </span>
                        {firstEntry?.name && (
                          <span className="text-sm text-[#93a79d] truncate max-w-[250px]">
                            {firstEntry.name}
                          </span>
                        )}
                      </div>
                      <div className="flex flex-wrap items-center gap-3 text-sm text-[#6f8a7d] mt-0.5">
                        {firstEntry?.org && (
                          <span className="flex items-center gap-1.5">
                            <Building size={14} className="text-[#4f6459]" />
                            {firstEntry.org}
                          </span>
                        )}
                        <span className="flex items-center gap-1.5">
                          <Shield size={14} className="text-[#4f6459]" />
                          {entries.length} networks
                        </span>
                        {info.ipv4 > 0 && (
                          <span className="flex items-center gap-1 text-[#22e57a] text-xs">
                            <Wifi size={12} />
                            {info.ipv4}
                          </span>
                        )}
                        {info.ipv6 > 0 && (
                          <span className="flex items-center gap-1 text-[#5c8aff] text-xs">
                            <WifiOff size={12} />
                            {info.ipv6}
                          </span>
                        )}
                        {hasBoth && (
                          <span className="flex items-center gap-1 px-1.5 py-0.5 rounded bg-[rgba(168,85,247,.08)] text-[10px] font-mono text-[#a78bfa]">
                            <Zap size={10} />
                            Dual
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex-shrink-0 flex items-center gap-2">
                      <Flag
                        countryCode={countryCode}
                        size={20}
                        variant="rounded"
                      />
                      <span className="text-xs font-mono text-[#4f6459]">
                        {countryCode.toUpperCase()}
                      </span>
                    </div>
                  </div>
                </Link>
              </motion.div>
            );
          })
        ) : (
          <div className="text-center py-12 bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] rounded-lg">
            <p className="text-[#6f8a7d] font-mono">
              No ASNs found matching "{searchQuery}"
            </p>
            <button
              onClick={clearSearch}
              className="mt-3 text-[#22e57a] hover:text-[#5cffa5] transition-colors font-mono text-sm"
            >
              Clear search
            </button>
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && filteredCount > 0 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          className="mt-6"
        />
      )}

      {/* Results count */}
      {filteredCount > 0 && (
        <div className="text-center text-xs font-mono text-[#4f6459]">
          Showing {startIndex + 1} - {Math.min(endIndex, filteredCount)} of{" "}
          {filteredCount.toLocaleString()} ASNs
          {searchQuery && ` (filtered from ${totalAsns.toLocaleString()})`}
        </div>
      )}
    </div>
  );
}
